import { createContext, useContext, useEffect, useState } from "react";

const ThemeContext = createContext({
  theme: "light",
  toggleTheme: () => {},
  mounted: false,
});

export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState("light");
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem("theme");
    const initial =
      stored ||
      (window.matchMedia("(prefers-color-scheme: dark)").matches
        ? "dark"
        : "light");
    setTheme(initial);
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted) return;
    document.documentElement.classList.toggle("dark", theme === "dark");
    localStorage.setItem("theme", theme);
  }, [theme, mounted]);

  const toggleTheme = () => setTheme((t) => (t === "light" ? "dark" : "light"));

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme, mounted }}>
      {children}
    </ThemeContext.Provider>
  );
}

export const useTheme = () => useContext(ThemeContext);

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
} from "react";
import { adminSettingsApi, adminAuditLogApi } from "../api/admin/adminApi";

const AdminDashboardContext = createContext();

export const useAdminDashboard = () => useContext(AdminDashboardContext);

export const AdminDashboardProvider = ({ children }) => {
  const [settings, setSettings] = useState(null);
  const [auditLogs, setAuditLogs] = useState([]);
  const [pulse, setPulse] = useState(null);
  const [volumeTrend, setVolumeTrend] = useState([]);

  const [isLoadingSettings, setIsLoadingSettings] = useState(false);
  const [isLoadingLogs, setIsLoadingLogs] = useState(false);
  const [error, setError] = useState(null);

  const fetchSettings = useCallback(async () => {
    setError(null);
    setIsLoadingSettings(true);
    try {
      const res = await adminSettingsApi.getSettings();
      setSettings(res.data.data || res.data);
    } catch (err) {
      console.error("Failed to fetch settings:", err);
      setError(err.response?.data?.message || "Failed to fetch settings");
    } finally {
      setIsLoadingSettings(false);
    }
  }, []);

  const fetchAuditLogs = useCallback(async (params = {}) => {
    setError(null);
    setIsLoadingLogs(true);
    try {
      const [logsRes, pulseRes, trendRes] = await Promise.all([
        adminAuditLogApi.getLogs(params),
        adminAuditLogApi.getPulse(),
        adminAuditLogApi.getVolumeTrend(),
      ]);
      setAuditLogs(logsRes.data.data || logsRes.data);
      setPulse(pulseRes.data.data || pulseRes.data);
      setVolumeTrend(trendRes.data.data || trendRes.data);
    } catch (err) {
      console.error("Failed to fetch audit logs:", err);
      setError(err.response?.data?.message || "Failed to fetch audit logs");
    } finally {
      setIsLoadingLogs(false);
    }
  }, []);

  const updatePlatformSettings = async (data) => {
    setError(null);
    const previousSettings = settings;
    setSettings((prev) => ({
      ...prev,
      platform: { ...prev?.platform, ...data },
    }));
    try {
      await adminSettingsApi.updatePlatformSettings(data);
      // Let the optimistic update hold, fetch in background just to sync
      fetchSettings();
    } catch (err) {
      setSettings(previousSettings);
      setError(err.response?.data?.message || "Update failed");
      throw err;
    }
  };

  const updateProfile = async (data) => {
    setError(null);
    const previousSettings = settings;
    setSettings((prev) => ({
      ...prev,
      profile: { ...prev?.profile, ...data },
    }));
    try {
      await adminSettingsApi.updateProfile(data);
      fetchSettings();
    } catch (err) {
      setSettings(previousSettings);
      setError(err.response?.data?.message || "Update failed");
      throw err;
    }
  };

  const updateNotifications = async (data) => {
    setError(null);
    const previousSettings = settings;
    setSettings((prev) => ({
      ...prev,
      notifications: { ...prev?.notifications, ...data },
    }));
    try {
      await adminSettingsApi.updateNotifications(data);
      fetchSettings();
    } catch (err) {
      setSettings(previousSettings);
      setError(err.response?.data?.message || "Update failed");
      throw err;
    }
  };

  // Initial load
  useEffect(() => {
    fetchSettings();
    // Don't fetch logs immediately to save DB if they don't visit the log page.
    // They can trigger fetchAuditLogs manually when they visit AuditLog.jsx.
  }, [fetchSettings]);

  const value = {
    settings,
    auditLogs,
    pulse,
    volumeTrend,
    isLoadingSettings,
    isLoadingLogs,
    error,
    fetchSettings,
    fetchAuditLogs,
    updatePlatformSettings,
    updateProfile,
    updateNotifications,
  };

  return (
    <AdminDashboardContext.Provider value={value}>
      {children}
    </AdminDashboardContext.Provider>
  );
};

import React, { createContext, useState, useCallback } from "react";
import * as incubationApi from "../api/startup/incubationApi";
import * as submissionApi from "../api/startup/submissionApi";
import * as tractionApi from "../api/startup/tractionApi";
import * as mvpApi from "../api/startup/mvpApi";

export const IncubationContext = createContext(null);

export const IncubationProvider = ({ children }) => {
  // Launch state
  const [launchOverview, setLaunchOverview] = useState(null);
  const [launchChecklist, setLaunchChecklist] = useState(null);
  const [launchSubmission, setLaunchSubmission] = useState(null);

  // Traction state
  const [tractionOverview, setTractionOverview] = useState(null);
  const [tractionChecklist, setTractionChecklist] = useState(null);
  const [tractionMetrics, setTractionMetrics] = useState([]);
  const [tractionSubmission, setTractionSubmission] = useState(null);
  const [tractionReviewStatus, setTractionReviewStatus] = useState(null);

  // MVP state
  const [mvpStage, setMvpStage] = useState(null);
  const [mvpChecklist, setMvpChecklist] = useState(null);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleError = (err, shouldThrow = true) => {
    const msg =
      err.response?.data?.message || err.message || "An error occurred";
    setError(msg);
    if (shouldThrow) throw new Error(msg);
  };

  // Launch methods
  const fetchLaunchOverview = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await incubationApi.getLaunchOverview();
      setLaunchOverview(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const fetchLaunchChecklist = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await incubationApi.getLaunchChecklist();
      setLaunchChecklist(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const fetchLaunchSubmission = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await incubationApi.getLaunchSubmission();
      setLaunchSubmission(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const submitLaunch = useCallback(
    async (payload) => {
      setIsLoading(true);
      setError(null);
      try {
        const res = await submissionApi.submitLaunch(payload);
        await fetchLaunchSubmission();
        await fetchLaunchOverview();
        return res;
      } catch (err) {
        handleError(err, true);
      } finally {
        setIsLoading(false);
      }
    },
    [fetchLaunchSubmission, fetchLaunchOverview],
  );

  const saveLaunchDraft = useCallback(
    async (payload) => {
      setIsLoading(true);
      setError(null);
      try {
        const res = await submissionApi.saveLaunchDraft(payload);
        await fetchLaunchSubmission();
        return res;
      } catch (err) {
        handleError(err, true);
      } finally {
        setIsLoading(false);
      }
    },
    [fetchLaunchSubmission],
  );

  // Traction methods
  const fetchTractionOverview = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await incubationApi.getTractionOverview();
      setTractionOverview(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const fetchTractionChecklist = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await incubationApi.getTractionChecklist();
      setTractionChecklist(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const fetchTractionMetrics = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await tractionApi.getTractionMetrics();
      setTractionMetrics(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const addTractionMetric = useCallback(
    async (payload) => {
      setIsLoading(true);
      setError(null);
      try {
        // Optimistic update
        setTractionMetrics((prev) => [...prev, payload]);
        const res = await tractionApi.addTractionMetric(payload);
        await fetchTractionMetrics();
        return res;
      } catch (err) {
        // Revert optimistic update? For simplicity just handle error
        handleError(err, true);
      } finally {
        setIsLoading(false);
      }
    },
    [fetchTractionMetrics],
  );

  const submitTraction = useCallback(
    async (payload) => {
      setIsLoading(true);
      setError(null);
      try {
        const res = await tractionApi.submitTraction(payload);
        await fetchTractionOverview();
        return res;
      } catch (err) {
        handleError(err, true);
      } finally {
        setIsLoading(false);
      }
    },
    [fetchTractionOverview],
  );

  // MVP methods
  const fetchMvpStage = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await mvpApi.getMvpStage();
      setMvpStage(data);
    } catch (err) {
      handleError(err, false);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const value = {
    launchOverview,
    launchChecklist,
    launchSubmission,
    tractionOverview,
    tractionChecklist,
    tractionMetrics,
    tractionSubmission,
    tractionReviewStatus,
    mvpStage,
    mvpChecklist,
    isLoading,
    error,
    setError,
    fetchLaunchOverview,
    fetchLaunchChecklist,
    fetchLaunchSubmission,
    submitLaunch,
    saveLaunchDraft,
    fetchTractionOverview,
    fetchTractionChecklist,
    fetchTractionMetrics,
    addTractionMetric,
    submitTraction,
    fetchMvpStage,
  };

  return (
    <IncubationContext.Provider value={value}>
      {children}
    </IncubationContext.Provider>
  );
};

import React, { createContext, useState, useCallback } from "react";
import * as investorApi from "../api/investorApi";

export const InvestorContext = createContext(null);

export const InvestorProvider = ({ children }) => {
  const [watchlist, setWatchlist] = useState([]);
  const [stats, setStats] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleError = (err, shouldThrow = true) => {
    const msg =
      err.response?.data?.message || err.message || "An error occurred";
    setError(msg);
    if (shouldThrow) throw new Error(msg);
  };

  const fetchWatchlist = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await investorApi.getWatchlist();
      setWatchlist(data);
    } catch (err) {
      handleError(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const addToWatchlist = useCallback(async (startupId) => {
    setError(null);
    setWatchlist((prev) => [
      ...prev,
      { _id: startupId, startup: { _id: startupId } },
    ]);
    try {
      await investorApi.addToWatchlist(startupId);
    } catch (err) {
      setWatchlist((prev) =>
        prev.filter((item) => item.startup?._id !== startupId),
      );
      handleError(err, false);
    }
  }, []);

  const removeFromWatchlist = useCallback(async (startupId) => {
    setError(null);
    let removedItem = null;
    setWatchlist((prev) => {
      const idx = prev.findIndex((item) => item.startup?._id === startupId);
      if (idx > -1) removedItem = prev[idx];
      return prev.filter((item) => item.startup?._id !== startupId);
    });
    try {
      await investorApi.removeFromWatchlist(startupId);
    } catch (err) {
      if (removedItem) setWatchlist((prev) => [...prev, removedItem]);
      handleError(err, false);
    }
  }, []);

  const fetchStats = useCallback(async () => {
    setIsLoading(true);
    try {
      const data = await investorApi.getInvestorStats();
      setStats(data);
    } catch (err) {
      handleError(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const trackPitchView = useCallback(async (startupId) => {
    try {
      await investorApi.trackPitchView(startupId);
    } catch (err) {
      console.error("Failed to track pitch view:", err);
    }
  }, []);

  const value = {
    watchlist,
    stats,
    isLoading,
    error,
    setError,
    fetchWatchlist,
    addToWatchlist,
    removeFromWatchlist,
    fetchStats,
    trackPitchView,
  };

  return (
    <InvestorContext.Provider value={value}>
      {children}
    </InvestorContext.Provider>
  );
};

