                  <div className="flex flex-wrap gap-2 mb-4">
                    {o.tags.map((t) => (
                      <span
                        key={t}
                        className="px-2 py-1 bg-canvas-bg text-text-muted font-inter text-caption rounded"
                      >
                        {t}
                      </span>
                    ))}
