    setErrorMsg("");
    investorApi
      .filterPitches({})
      .then((res) => {
        setDecks(res.data || res || []);
      })
      .catch((err) => {
        console.error(err);
        setDecks([]);
        setErrorMsg(
          err?.response?.data?.message ||
            err?.message ||
            "Failed to load pitch decks. Please try again.",
        );
      })
      .finally(() => setLoading(false));
  }, []);

  const filteredDecks = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return decks;
    return decks.filter((deck) => {
      const startupName = deck.startup_id?.startup_name || "";
      return (
        startupName.toLowerCase().includes(q) ||
        (deck.industry || "").toLowerCase().includes(q)
