                    ))}
                  </div>

                  <p className="font-inter text-small text-text-body leading-relaxed mb-4 line-clamp-3">
                    {description}
                  </p>

                  <div className="flex items-center justify-between pt-3 border-t border-border-subtle">
                    <div>
                      <p className="font-inter text-caption uppercase tracking-wider text-text-muted">
                        Target Raise
                      </p>
                      <p className="font-poppins font-semibold text-body text-text-heading">
                        {targetRaise}
                      </p>
                    </div>
                  </div>
                </div>

                <div
                  className={`flex items-center gap-2 ${viewMode === "list" ? "mt-4 md:mt-0 shrink-0" : "mt-4"}`}
                >
                  <Link
                    to={`/investor/pitch-decks/review?id=${deck._id}`}
                    className="flex-1 inline-flex items-center justify-center gap-2 bg-action-bg text-action-text font-poppins font-semibold text-small px-4 py-2.5 rounded-md hover:opacity-90 transition-all"
                  >
                    <Play size={14} strokeWidth={2} />
                    View Pitch Deck
                  </Link>
                </div>
              </div>
            );
          })}
        </div>
      )}

      <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mt-8 pt-6 border-t border-border-subtle">
        <p className="font-inter text-small text-text-muted">
          Showing {filteredDecks.length} of {decks.length} submissions
        </p>
        <div className="flex items-center gap-1">
          <button
            type="button"
            disabled
            className="p-2 rounded-md border border-border-subtle text-text-muted disabled:opacity-40 disabled:cursor-not-allowed"
