import {
  submitIdea,
  saveDraft,
  getSubmissionStatus,
} from "@/api/startup/submissionApi";

const FIELDS = [
  {
    name: "startupName",
    label: "Startup Name / Title",
    type: "input",
    placeholder: "e.g. EcoSphere Analytics",
    hint: "Make it memorable and professional.",
