source:
import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  ChevronRight,
  Info,
  Link2,
  FileText,
  Share2,
  Send,
  Globe,
  Camera,
  X as XIcon,
  PlayCircle,
  CheckCircle2,
  Radio,
  CircleDashed,
  Lightbulb,
} from "lucide-react";
import DashboardShell from "@/components/dashboard/DashboardShell";
import Input from "@/components/ui/Input";
import Button from "@/components/ui/Button";
import { useDocumentTitle } from "@/hooks/useDocumentTitle";
import { useIncubation } from "@/hooks/useIncubation";

const INDUSTRIES = [
  "Select Industry",
  "Fintech",
  "Healthtech",
  "SaaS",
  "EdTech",
];
const FUNDING = [
  "Select Status",
  "Bootstrapped",
  "Pre-seed",
  "Seed",
  "Series A+",
];

const TEXTAREA_CLASS =
  "w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter p-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all resize-none";

const SELECT_CLASS =
  "w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] px-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all";

const CHECKLIST = [
  { label: "Program Benchmarks", desc: "Completed in Stage 4", status: "done" },
  {
    label: "Launch Form",
    desc: "Currently filling final details",
    status: "current",
  },
  {
    label: "Graduation Review",
    desc: "Unlocks after submission",
    status: "upcoming",
  },
];

const READINESS = [
  { label: "Market Validation", done: true },
  { label: "Financial Projections", done: true },
  { label: "Product Demo", done: false },
];

export default function LaunchSubmissionPage() {
  useDocumentTitle("Launch Submission — BOCC");
  const navigate = useNavigate();

  const [form, setForm] = useState({
    startupName: "",
    productName: "",
    launchDate: "",
    industry: INDUSTRIES[0],
    teamSize: "",
    funding: FUNDING[0],
    websiteUrl: "",
    liveUrl: "",
    storeLink: "",
    demoUrl: "",
    description: "",
    notes: "",
    linkedin: "",
    instagram: "",
    twitter: "",
    youtube: "",
  });

  const update = (field) => (e) =>
    setForm((prev) => ({ ...prev, [field]: e.target.value }));

  const {
    submitLaunch,
    saveLaunchDraft,
    fetchLaunchSubmission,
    launchSubmission,
    isLoading: isContextLoading,
  } = useIncubation();
  const [toastMsg, setToastMsg] = useState({ type: "", text: "" });

  // Fetch draft data on mount
  useEffect(() => {
    fetchLaunchSubmission();
  }, [fetchLaunchSubmission]);

  // Sync draft data into form when it loads
  useEffect(() => {
    if (launchSubmission) {
      setForm({
        startupName: launchSubmission.startup_name || "",
        productName: launchSubmission.product_name || "",
        launchDate: launchSubmission.launch_date
          ? launchSubmission.launch_date.split("T")[0]
          : "",
        industry: launchSubmission.industry || INDUSTRIES[0],
        fundingStatus: launchSubmission.funding_status || FUNDING[0],
        demoLink: launchSubmission.demo_link || "",
        socials: {
          twitter: launchSubmission.social?.twitter || "",
          linkedin: launchSubmission.social?.linkedin || "",
        },
      });
    }
  }, [launchSubmission]);

  const isSavingDraft = isContextLoading;
  const isSubmitting = isContextLoading;

  const handleSubmit = async () => {
    setToastMsg({ type: "", text: "" });
    try {
      await submitLaunch(form);
      navigate("/build-startup/journey/launch/pitch-deck");
    } catch (err) {
      setToastMsg({
        type: "error",
        text: err.response?.data?.message || err.message || "Submission failed",
      });
    }
  };

  const handleSaveDraft = async () => {
    setToastMsg({ type: "", text: "" });
    try {
      await saveLaunchDraft(form);
      setToastMsg({ type: "success", text: "Draft Saved" });
      setTimeout(() => setToastMsg({ type: "", text: "" }), 3000);
    } catch (err) {
      setToastMsg({
        type: "error",
        text:
          err.response?.data?.message || err.message || "Failed to save draft",
      });
    }
  };

  return (
    <DashboardShell pageId="launch-submission">
      <nav className="mb-2 flex items-center gap-2 text-text-muted font-inter font-normal text-small">
        <Link
          to="/dashboard"
          className="hover:text-text-heading transition-colors"
        >
          Dashboard
        </Link>
        <ChevronRight size={14} strokeWidth={2} />
        <Link
          to="/build-startup/journey/launch"
          className="hover:text-text-heading transition-colors"
        >
          Stage 5 – Launch
        </Link>
        <ChevronRight size={14} strokeWidth={2} />
        <span className="text-text-heading font-semibold">
          Launch Submission
        </span>
      </nav>

      <div className="mb-10">
        <h1 className="font-poppins font-semibold text-page text-text-heading mb-2">
          Launch Submission
        </h1>
        <p className="font-inter text-body text-text-body max-w-2xl">
          Please provide the final details of your startup launch for graduation
          review. Ensure all links are active and descriptions are
          comprehensive.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8 space-y-6">
          <section className="bg-surface-white border border-border-subtle rounded-lg p-8">
            <div className="flex items-center gap-3 mb-6">
              <Info size={20} strokeWidth={2} className="text-text-heading" />
              <h3 className="font-poppins font-semibold text-body text-text-heading">
                General Information
              </h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <Input
                id="startupName"
                label="Startup Name"
                placeholder="e.g. Acme Corp"
                value={form.startupName}
                onChange={update("startupName")}
              />
              <Input
                id="productName"
                label="Product Name"
                placeholder="e.g. Acme Dash"
                value={form.productName}
                onChange={update("productName")}
              />
              <Input
                id="launchDate"
                label="Launch Date"
                type="date"
                value={form.launchDate}
                onChange={update("launchDate")}
              />
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="industry"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  Industry
                </label>
                <select
                  id="industry"
                  value={form.industry}
                  onChange={update("industry")}
                  className={SELECT_CLASS}
                >
                  {INDUSTRIES.map((i) => (
                    <option key={i}>{i}</option>
                  ))}
                </select>
              </div>
              <Input
                id="teamSize"
                label="Current Team Size"
                type="number"
                placeholder="0"
                value={form.teamSize}
                onChange={update("teamSize")}
              />
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="funding"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  Funding Status (Optional)
                </label>
                <select
                  id="funding"
                  value={form.funding}
                  onChange={update("funding")}
                  className={SELECT_CLASS}
                >
                  {FUNDING.map((f) => (
                    <option key={f}>{f}</option>
                  ))}
                </select>
              </div>
            </div>
          </section>

          <section className="bg-surface-white border border-border-subtle rounded-lg p-8">
            <div className="flex items-center gap-3 mb-6">
              <Link2 size={20} strokeWidth={2} className="text-text-heading" />
              <h3 className="font-poppins font-semibold text-body text-text-heading">
                Product &amp; Demo Links
              </h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <Input
                id="websiteUrl"
                label="Website URL"
                placeholder="https://..."
                value={form.websiteUrl}
                onChange={update("websiteUrl")}
              />
              <Input
                id="liveUrl"
                label="Live Product URL"
                placeholder="app...."
                value={form.liveUrl}
                onChange={update("liveUrl")}
              />
              <Input
                id="storeLink"
                label="App Store / Play Store Link"
                placeholder="Link to mobile app"
                value={form.storeLink}
                onChange={update("storeLink")}
              />
              <Input
                id="demoUrl"
                label="Demo Video URL"
                placeholder="YouTube, Loom, or Vimeo link"
                value={form.demoUrl}
                onChange={update("demoUrl")}
              />
            </div>
          </section>

          <section className="bg-surface-white border border-border-subtle rounded-lg p-8">
            <div className="flex items-center gap-3 mb-6">
              <FileText
                size={20}
                strokeWidth={2}
                className="text-text-heading"
              />
              <h3 className="font-poppins font-semibold text-body text-text-heading">
                Descriptions
              </h3>
            </div>
            <div className="space-y-5">
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="description"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  Startup Description
                </label>
                <textarea
                  id="description"
                  rows={4}
                  placeholder="What problem are you solving and how? Max 500 characters."
                  value={form.description}
                  onChange={update("description")}
                  className={TEXTAREA_CLASS}
                />
              </div>
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="notes"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  Additional Notes
                </label>
                <textarea
                  id="notes"
                  rows={3}
                  placeholder="Any specific instructions for the graduation committee?"
                  value={form.notes}
                  onChange={update("notes")}
                  className={TEXTAREA_CLASS}
                />
              </div>
            </div>
          </section>

          <section className="bg-surface-white border border-border-subtle rounded-lg p-8">
            <div className="flex items-center gap-3 mb-6">
              <Share2 size={20} strokeWidth={2} className="text-text-heading" />
              <h3 className="font-poppins font-semibold text-body text-text-heading">
                Social Media Presence
              </h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="linkedin"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  LinkedIn
                </label>
                <div className="relative">
                  <Globe
                    size={16}
                    strokeWidth={2}
                    className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted"
                  />
                  <input
                    id="linkedin"
                    value={form.linkedin}
                    onChange={update("linkedin")}
                    placeholder="linkedin.com/company/..."
                    className="w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] pl-10 pr-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all"
                  />
                </div>
              </div>
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="instagram"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  Instagram
                </label>
                <div className="relative">
                  <Camera
                    size={16}
                    strokeWidth={2}
                    className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted"
                  />
                  <input
                    id="instagram"
                    value={form.instagram}
                    onChange={update("instagram")}
                    placeholder="@handle"
                    className="w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] pl-10 pr-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all"
                  />
                </div>
              </div>
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="twitter"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  Twitter/X
                </label>
                <div className="relative">
                  <XIcon
                    size={16}
                    strokeWidth={2}
                    className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted"
                  />
                  <input
                    id="twitter"
                    value={form.twitter}
                    onChange={update("twitter")}
                    placeholder="@handle"
                    className="w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] pl-10 pr-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all"
                  />
                </div>
              </div>
              <div className="flex flex-col gap-1">
                <label
                  htmlFor="youtube"
                  className="text-caption font-medium text-text-heading font-inter"
                >
                  YouTube
                </label>
                <div className="relative">
                  <PlayCircle
                    size={16}
                    strokeWidth={2}
                    className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted"
                  />
                  <input
                    id="youtube"
                    value={form.youtube}
                    onChange={update("youtube")}
                    placeholder="youtube.com/@channel"
                    className="w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] pl-10 pr-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all"
                  />
                </div>
              </div>
            </div>
          </section>

          <div className="flex items-center gap-4 py-6 border-t border-divider-line">
            <Button
              onClick={handleSubmit}
              disabled={isSubmitting || isSavingDraft}
            >
              {isSubmitting ? "Submitting..." : "Submit Launch Details"}
              {!isSubmitting && <Send size={16} strokeWidth={2} />}
            </Button>
            <Button
              variant="outline"
              onClick={handleSaveDraft}
              disabled={isSubmitting || isSavingDraft}
            >
              {isSavingDraft ? "Saving..." : "Save Draft"}
            </Button>
            {toastMsg.text && (
              <span
                className={`text-sm font-medium ${toastMsg.type === "error" ? "text-red-500" : "text-green-600"}`}
              >
                {toastMsg.text}
              </span>
            )}
          </div>
        </div>

        <div className="lg:col-span-4 space-y-6">
          <div className="bg-canvas-bg border border-border-subtle rounded-lg p-6">
            <h4 className="font-inter font-semibold text-caption text-text-muted uppercase tracking-widest mb-4">
              Submission Progress
            </h4>
            <div className="flex items-center justify-between mb-2">
              <span className="font-poppins font-semibold text-small text-text-heading">
                Launch Submission
              </span>
              <span className="px-2 py-1 bg-brand-black text-white rounded text-[10px] font-inter font-semibold uppercase">
                In Progress
              </span>
            </div>
            <div className="w-full bg-surface-white h-2 rounded-full overflow-hidden mb-3">
              <div
                className="bg-brand-black h-full rounded-full transition-all"
                style={{ width: "45%" }}
              />
            </div>
            <p className="font-inter text-caption text-text-muted">
              8 of 14 fields completed. Fill in all required fields to enable
              the submission button.
            </p>
          </div>

          <div className="bg-surface-white border border-border-subtle rounded-lg p-6">
            <h4 className="font-inter font-semibold text-caption text-text-muted uppercase tracking-widest mb-6">
              Final Checklist
            </h4>
            <ul className="space-y-5">
              {CHECKLIST.map(({ label, desc, status }) => (
                <li
                  key={label}
                  className={`flex items-start gap-3 ${status === "upcoming" ? "opacity-40" : ""}`}
                >
                  {status === "done" && (
                    <CheckCircle2
                      size={20}
                      strokeWidth={2}
                      className="text-text-heading shrink-0"
                    />
                  )}
                  {status === "current" && (
                    <Radio
                      size={20}
                      strokeWidth={2}
                      className="text-text-heading shrink-0"
                    />
                  )}
                  {status === "upcoming" && (
                    <CircleDashed
                      size={20}
                      strokeWidth={2}
                      className="text-text-muted shrink-0"
                    />
                  )}
                  <div>
                    <p className="font-poppins font-semibold text-small text-text-heading">
                      {label}
                    </p>
                    <p className="font-inter text-caption text-text-muted">
                      {desc}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          </div>

          <div className="bg-surface-white border border-dashed border-border-subtle rounded-lg p-6">
            <div className="flex items-center gap-2 mb-3 text-text-muted">
              <Lightbulb size={18} strokeWidth={2} />
              <h4 className="font-inter font-semibold text-caption uppercase tracking-wider">
                Expert Tip
              </h4>
            </div>
            <p className="font-inter text-small text-text-muted italic">
              "The graduation committee values clarity over jargon. Make your
              demo video short (under 3 mins) and ensure your links are
              accessible to external reviewers."
            </p>
          </div>

          <div className="bg-surface-white border border-border-subtle rounded-lg p-6">
            <h4 className="font-inter font-semibold text-caption text-text-muted uppercase tracking-widest mb-4">
              Launch Readiness
            </h4>
            <div className="space-y-3">
              {READINESS.map(({ label, done }) => (
                <div
                  key={label}
                  className="flex justify-between items-center font-inter text-small"
                >
                  <span className="text-text-muted">{label}</span>
                  {done ? (
                    <CheckCircle2
                      size={16}
                      strokeWidth={2}
                      className="text-text-heading"
                    />
                  ) : (
                    <span className="w-2 h-2 rounded-full bg-border-subtle" />
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </DashboardShell>
  );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  Laptop2,
  Package,
  Check,
  ChevronRight,
  ArrowRight,
  AlertCircle,
} from "lucide-react";
import DashboardShell from "@/components/dashboard/DashboardShell";
import { useDocumentTitle } from "@/hooks/useDocumentTitle";
import { setProductType } from "@/api/startup/mvpApi";

const OPTIONS = [
  {
    key: "digital",
    icon: Laptop2,
    title: "Digital Product",
    desc: "A web app, mobile app, or SaaS platform — validated with a live, clickable build.",
    points: [
      "Ship faster, iterate in days",
      "Real usage data from day one",
      "Lower upfront cost",
    ],
  },
  {
    key: "physical",
    icon: Package,
    title: "Physical Product",
    desc: "A tangible good — validated with a prototype, sample run, or pre-order campaign.",
    points: [
      "Tactile feedback from real users",
      "Manufacturing/supply-chain learnings",
      "Longer iteration cycles",
    ],
  },
];

export default function ChooseProductTypePage() {
  useDocumentTitle("Choose Your Product Type — BOCC");
  const navigate = useNavigate();
  const [selected, setSelected] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const handleContinue = async () => {
    try {
      setErrorMsg("");
      setIsSubmitting(true);
      await setProductType({ type: selected });
      navigate("/build-startup/journey/mvp/submit");
    } catch (err) {
      console.error(err);
      setErrorMsg(
        err.response?.data?.message ||
          err.message ||
          "Failed to save product type. Please try again.",
      );
      setIsSubmitting(false);
    }
  };

  return (
    <DashboardShell pageId="choose-product-type">
      <nav className="mb-2 flex items-center gap-2 text-text-muted font-inter font-normal text-small">
        <Link
          to="/dashboard"
          className="hover:text-text-heading transition-colors"
        >
          Dashboard
        </Link>
        <ChevronRight size={14} strokeWidth={2} />
        <Link
          to="/build-startup/journey/mvp"
          className="hover:text-text-heading transition-colors"
        >
          MVP
        </Link>
        <ChevronRight size={14} strokeWidth={2} />
        <span className="text-text-heading font-semibold">
          Choose Product Type
        </span>
      </nav>

      <h1 className="font-poppins font-semibold text-page text-text-heading mb-1">
        Choose Your Product Type
      </h1>
      <p className="font-inter text-body text-text-body mb-8 max-w-2xl">
        This tailors the guidance and templates you'll see through the rest of
        the MVP stage.
      </p>

      {errorMsg && (
        <div className="mb-6 p-3 bg-error/15 border border-error/30 text-error rounded-md text-small flex items-center gap-2">
          <AlertCircle size={16} className="shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-8">
        {OPTIONS.map(({ key, icon: Icon, title, desc, points }) => {
          const isSelected = selected === key;
          return (
            <button
              key={key}
              type="button"
              onClick={() => setSelected(key)}
              className={`text-left p-6 rounded-lg border-2 transition-colors ${
                isSelected
                  ? "border-brand-black bg-surface-white shadow-card"
                  : "border-border-subtle bg-surface-white hover:border-text-muted"
              }`}
            >
              <div className="flex items-center justify-between mb-4">
                <div className="w-11 h-11 rounded-lg bg-canvas-bg border border-border-subtle flex items-center justify-center">
                  <Icon size={22} strokeWidth={2} className="text-text-body" />
                </div>
                {isSelected && (
                  <div className="w-6 h-6 rounded-full bg-brand-black flex items-center justify-center">
                    <Check size={14} strokeWidth={3} className="text-white" />
                  </div>
                )}
              </div>
              <h3 className="font-poppins font-semibold text-card text-text-heading mb-1">
                {title}
              </h3>
              <p className="font-inter text-small text-text-muted mb-4">
                {desc}
              </p>
              <ul className="space-y-1.5">
                {points.map((p) => (
                  <li
                    key={p}
                    className="flex items-center gap-2 font-inter text-small text-text-body"
                  >
                    <Check
                      size={14}
                      strokeWidth={2}
                      className="text-success shrink-0"
                    />
                    {p}
                  </li>
                ))}
              </ul>
            </button>
          );
        })}
      </div>

      <button
        type="button"
        disabled={!selected || isSubmitting}
        onClick={handleContinue}
        className="inline-flex items-center gap-2 bg-action-bg text-action-text px-8 py-3 rounded-md hover:opacity-90 active:scale-[0.98] transition-all font-poppins font-semibold text-body disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:opacity-40"
      >
        {isSubmitting ? "Saving..." : "Continue"}
        {!isSubmitting && <ArrowRight size={18} strokeWidth={2} />}
      </button>
    </DashboardShell>
  );
}

import { useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  UploadCloud,
  File,
  Trash2,
  CheckCircle2,
  ChevronRight,
  Clock,
  AlertCircle,
} from "lucide-react";
import DashboardShell from "@/components/dashboard/DashboardShell";
import { useDocumentTitle } from "@/hooks/useDocumentTitle";
import api from "@/api/axiosInstance";

const ACCEPTED_DOCS = [
  "Incubation Acceptance Letter",
  "Offer Letter",
  "Certificate of Incubation",
  "Letter of Intent",
  "Incubator Agreement",
];

const STEPS = [
  "Upload proof",
  "Admin review",
  "Status updated",
  "Stage 4 unlocked",
];

export default function IncubationProofSubmissionPage() {
  useDocumentTitle("Incubation Proof Submission — BOCC");
  const navigate = useNavigate();
  const fileInputRef = useRef(null);

  const [form, setForm] = useState({
    startupName: "EcoSphere Analytics",
    incubatorName: "",
    incubatorWebsite: "",
    dateOfAcceptance: "",
    duration: "",
    programName: "",
    notes: "",
  });
  const [file, setFile] = useState(null);

  const updateField = (key) => (e) =>
    setForm((prev) => ({ ...prev, [key]: e.target.value }));

  const handleFile = (fileList) => {
    if (fileList[0])
      setFile({ name: fileList[0].name, size: fileList[0].size });
  };

  const [errorMsg, setErrorMsg] = useState("");
  const [successMsg, setSuccessMsg] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [savingDraft, setSavingDraft] = useState(false);

  const canSubmit = form.incubatorName.trim().length > 0 && !!file;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!canSubmit) return;
    setErrorMsg("");
    setIsSubmitting(true);

    try {
      const formData = new FormData();
      Object.entries(form).forEach(([k, v]) => formData.append(k, v));
      if (file && fileInputRef.current?.files?.[0]) {
        formData.append("document", fileInputRef.current.files[0]);
      }

      await api.post("/incubation/proof", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      navigate("/build-startup/journey/mvp/incubation-verification");
    } catch (err) {
      setErrorMsg(
        err.response?.data?.message ||
          err.message ||
          "Failed to submit incubation proof.",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSaveDraft = async () => {
    setErrorMsg("");
    setSuccessMsg("");
    setSavingDraft(true);
    try {
      await api.patch("/incubation/proof/draft", form);
      setSuccessMsg("Draft saved successfully.");
      setTimeout(() => setSuccessMsg(""), 3000);
    } catch (err) {
      setErrorMsg(
        err.response?.data?.message || err.message || "Failed to save draft.",
      );
    } finally {
      setSavingDraft(false);
    }
  };

  return (
    <DashboardShell pageId="incubation-proof-submission">
      <nav className="mb-2 flex items-center gap-2 text-text-muted font-inter font-normal text-small">
        <Link
          to="/dashboard"
          className="hover:text-text-heading transition-colors"
        >
          Dashboard
        </Link>
        <ChevronRight size={14} strokeWidth={2} />
        <Link
          to="/build-startup/journey/mvp"
          className="hover:text-text-heading transition-colors"
        >
          MVP
        </Link>
        <ChevronRight size={14} strokeWidth={2} />
        <span className="text-text-heading font-semibold">
          Incubation Proof
        </span>
      </nav>

      <h1 className="font-poppins font-semibold text-page text-text-heading mb-1">
        Incubation Proof Submission
      </h1>
      <p className="font-inter text-body text-text-body mb-6 max-w-2xl">
        Upload your incubation acceptance proof to verify your startup's
        incubation status. Once verified, you'll unlock the next stage of your
        startup journey.
      </p>

      {errorMsg && (
        <div className="mb-6 p-3 bg-error/15 border border-error/30 text-error rounded-md text-small flex items-center gap-2 max-w-2xl">
          <AlertCircle size={16} className="shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      {successMsg && (
        <div className="mb-6 p-3 bg-success/15 border border-success/30 text-success rounded-md text-small flex items-center gap-2 max-w-2xl">
          <CheckCircle2 size={16} className="shrink-0" />
          <span>{successMsg}</span>
        </div>
      )}

      <form
        onSubmit={handleSubmit}
        className="grid grid-cols-1 lg:grid-cols-12 gap-6"
      >
        <div className="lg:col-span-8 space-y-6">
          <div className="bg-surface-white border border-border-subtle rounded-lg shadow-card p-6 space-y-4">
            <h3 className="font-poppins font-semibold text-body text-text-heading">
              Incubation Details
            </h3>

            <div>
              <label className="font-poppins font-semibold text-caption text-text-muted uppercase tracking-wider block mb-1.5">
                Startup Name
              </label>
              <input
                type="text"
                value={form.startupName}
                disabled
                className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-muted font-inter text-body py-2.5 px-3 cursor-not-allowed"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="font-poppins font-semibold text-caption text-text-muted uppercase tracking-wider block mb-1.5">
                  Incubator Name
                </label>
                <input
                  type="text"
                  value={form.incubatorName}
                  onChange={updateField("incubatorName")}
                  placeholder="Enter incubator name"
                  className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-body font-inter text-body py-2.5 px-3 focus:outline-none focus:ring-1 focus:ring-brand-black"
                />
              </div>
              <div>
                <label className="font-poppins font-semibold text-caption text-text-muted uppercase tracking-wider block mb-1.5">
                  Incubator Website (Optional)
                </label>
                <input
                  type="url"
                  value={form.incubatorWebsite}
                  onChange={updateField("incubatorWebsite")}
                  placeholder="https://..."
                  className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-body font-inter text-body py-2.5 px-3 focus:outline-none focus:ring-1 focus:ring-brand-black"
                />
              </div>
              <div>
                <label className="font-poppins font-semibold text-caption text-text-muted uppercase tracking-wider block mb-1.5">
                  Date of Acceptance
                </label>
                <input
                  type="date"
                  value={form.dateOfAcceptance}
                  onChange={updateField("dateOfAcceptance")}
                  className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-body font-inter text-body py-2.5 px-3 focus:outline-none focus:ring-1 focus:ring-brand-black"
                />
              </div>
              <div>
                <label className="font-poppins font-semibold text-caption text-text-muted uppercase tracking-wider block mb-1.5">
                  Incubation Duration (e.g. 6 months)
                </label>
                <input
                  type="text"
                  value={form.duration}
                  onChange={updateField("duration")}
                  placeholder="Enter duration"
                  className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-body font-inter text-body py-2.5 px-3 focus:outline-none focus:ring-1 focus:ring-brand-black"
                />
              </div>
            </div>

            <div>
              <label className="font-poppins font-semibold text-caption text-text-muted uppercase tracking-wider block mb-1.5">
                Incubation Program Name (Optional)
              </label>
              <input
                type="text"
                value={form.programName}
                onChange={updateField("programName")}
                placeholder="Enter program-specific name"
                className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-body font-inter text-body py-2.5 px-3 focus:outline-none focus:ring-1 focus:ring-brand-black"
              />
            </div>
          </div>

          <div className="bg-surface-white border border-border-subtle rounded-lg shadow-card p-6">
            <h3 className="font-poppins font-semibold text-body text-text-heading mb-4">
              Document Upload
            </h3>
            <div
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                e.preventDefault();
                handleFile(e.dataTransfer.files);
              }}
              className="flex flex-col items-center justify-center gap-2 border-2 border-dashed border-border-subtle rounded-lg py-10 text-center mb-3"
            >
              <UploadCloud
                size={26}
                strokeWidth={1.5}
                className="text-text-muted"
              />
              <p className="font-poppins font-semibold text-small text-text-heading">
                Drag &amp; Drop File
              </p>
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="font-inter text-small text-text-heading underline underline-offset-2"
              >
                or Browse Files
              </button>
              <input
                ref={fileInputRef}
                type="file"
                accept=".pdf,.jpg,.png"
                className="hidden"
                onChange={(e) => handleFile(e.target.files)}
              />
            </div>
            {file && (
              <div className="flex items-center gap-3 border border-border-subtle rounded-lg p-3">
                <File
                  size={18}
                  strokeWidth={2}
                  className="text-text-muted shrink-0"
                />
                <div className="min-w-0 flex-1">
                  <p className="font-poppins font-semibold text-small text-text-heading truncate">
                    {file.name}
                  </p>
                </div>
                <CheckCircle2
                  size={16}
                  strokeWidth={2}
                  className="text-success shrink-0"
                />
                <button
                  type="button"
                  onClick={() => setFile(null)}
                  aria-label="Remove file"
                >
                  <Trash2
                    size={16}
                    strokeWidth={2}
                    className="text-text-muted hover:text-error transition-colors"
                  />
                </button>
              </div>
            )}
          </div>

          <div className="bg-surface-white border border-border-subtle rounded-lg shadow-card p-6">
            <h3 className="font-poppins font-semibold text-body text-text-heading mb-1.5">
              Additional Notes (Optional)
            </h3>
            <textarea
              rows={3}
              value={form.notes}
              onChange={updateField("notes")}
              placeholder="Share any additional information about your incubation program."
              className="w-full bg-canvas-bg border border-border-subtle rounded-md text-text-body font-inter text-body py-2.5 px-3 focus:outline-none focus:ring-1 focus:ring-brand-black resize-none"
            />
          </div>
        </div>

        <div className="lg:col-span-4 space-y-4">
          <div className="bg-surface-white border border-border-subtle rounded-lg shadow-card p-5">
            <p className="font-inter font-semibold text-caption text-text-muted uppercase tracking-wider mb-3">
              Accepted Documents
            </p>
            <div className="space-y-2">
              {ACCEPTED_DOCS.map((doc) => (
                <div key={doc} className="flex items-center gap-2">
                  <CheckCircle2
                    size={14}
                    strokeWidth={2}
                    className="text-success shrink-0"
                  />
                  <p className="font-inter text-small text-text-body">{doc}</p>
                </div>
              ))}
            </div>
            <p className="font-inter text-caption text-text-muted mt-3">
              Max file size: 10MB per document.
            </p>
          </div>

          <div className="bg-surface-white border border-border-subtle rounded-lg shadow-card p-5">
            <p className="font-inter font-semibold text-caption text-text-muted uppercase tracking-wider mb-4">
              Verification Process
            </p>
            <div className="space-y-3">
              {STEPS.map((step, i) => (
                <div key={step} className="flex items-center gap-2.5">
                  <div
                    className={`w-5 h-5 rounded-full flex items-center justify-center font-inter text-caption shrink-0 ${i === 0 ? "bg-brand-black text-white" : "border border-border-subtle text-text-muted"}`}
                  >
                    {i + 1}
                  </div>
                  <p
                    className={`font-inter text-small ${i === 0 ? "text-text-heading font-semibold" : "text-text-muted"}`}
                  >
                    {step}
                  </p>
                </div>
              ))}
            </div>
            <div className="flex items-center gap-1.5 mt-4 pt-3 border-t border-divider-line">
              <Clock size={14} strokeWidth={2} className="text-text-muted" />
              <p className="font-inter text-caption text-text-muted">
                Est. time: 2–3 business days.
              </p>
            </div>
          </div>
        </div>

        <div className="lg:col-span-12 flex items-center gap-3 pt-6 border-t border-divider-line">
          <button
            type="submit"
            disabled={!canSubmit || isSubmitting || savingDraft}
            className="bg-action-bg text-action-text px-6 py-2.5 rounded-md hover:opacity-90 active:scale-[0.98] transition-all font-poppins font-semibold text-small disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSubmitting ? "Submitting..." : "Submit for Verification"}
          </button>
          <button
            type="button"
            onClick={handleSaveDraft}
            disabled={isSubmitting || savingDraft}
            className="border border-border-subtle text-text-heading px-6 py-2.5 rounded-md hover:bg-canvas-bg transition-colors font-poppins font-semibold text-small disabled:opacity-50"
          >
            {savingDraft ? "Saving..." : "Save Draft"}
          </button>
          <p className="font-inter text-caption text-text-muted ml-2">
            Your submission cannot be edited while it is under verification.
          </p>
        </div>
      </form>
    </DashboardShell>
  );
}

