                </span>
                <span className="font-inter text-caption text-text-heading">
                  {activeThread.college}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="font-inter text-caption text-text-muted">
                  Cohort
                </span>
                <span className="font-inter text-caption text-text-heading">
