import { useMemo, useState } from "react";
import {
  Search,
  Video,
  Clock,
  Calendar as CalendarIcon,
  AlertCircle,
} from "lucide-react";
import MentorShell from "@/components/mentor/MentorShell";
import ComingSoon from "@/components/ui/ComingSoon";
import Badge from "@/components/ui/Badge";
import { useDocumentTitle } from "@/hooks/useDocumentTitle";
import api from "@/api/axiosInstance";
import { useEffect } from "react";

const STATS = [
  { label: "Upcoming Meetings", value: "08" },
  { label: "Today's Meetings", value: "02" },
  { label: "Completed Sessions", value: "45" },
  { label: "Pending Confirmations", value: "03" },
];

const MEETINGS = [
  {
    id: 1,
    name: "Sarah Chen",
    startup: "EcoValve",
    stage: "Seed",
    title: "GTM Strategy Review",
    status: "Upcoming",
    date: "Oct 28, 2023",
    time: "2:00 PM (60 min)",
    location: "Google Meet",
    college: "MIT",
    agenda: [
      "Review Q3 sales targets",
      "Draft outbound sequence for Tier 1",
      "Discuss hiring roadmap for SDRs",
    ],
    studentNotes:
      "Hoping to get specific feedback on our pricing tiers for the new enterprise tier we're launching next month.",
  },
  {
    id: 2,
    name: "Marcus Thorne",
    startup: "GridLogic",
    stage: "Pre-Seed",
    title: "Product Roadmap Deep-dive",
    status: "Upcoming",
    date: "Oct 30, 2023",
    time: "10:30 AM (45 min)",
    location: "Google Meet",
    college: "Oxford University",
    agenda: [
      "Walk through Q1 roadmap",
      "Review technical architecture decisions",
    ],
    studentNotes:
      "Would like input on prioritizing the API integration versus the mobile app.",
  },
];

const OUTCOME_OPTIONS = [
  "Select outcome...",
  "Great progress",
  "Needs follow-up",
  "Blocked / needs help",
  "Session completed",
];

export default function MentorMeetingsPage() {
  useDocumentTitle("Meetings — BOCC");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedMeetingId, setSelectedMeetingId] = useState(MEETINGS[0].id);
  const [mentorNotes, setMentorNotes] = useState("");
  const [outcome, setOutcome] = useState(OUTCOME_OPTIONS[0]);
  const [saved, setSaved] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [successMsg, setSuccessMsg] = useState("");

  const selectedMeeting = MEETINGS.find((m) => m.id === selectedMeetingId);

  useEffect(() => {
    if (selectedMeetingId) {
      api
        .get(`/meeting/feedback?meetingId=${selectedMeetingId}`)
        .then((res) => {
          if (res.data && res.data.notes) {
            setMentorNotes(res.data.notes);
            if (res.data.outcome) setOutcome(res.data.outcome);
          } else {
            setMentorNotes("");
            setOutcome(OUTCOME_OPTIONS[0]);
          }
        })
        .catch((err) => {
          console.error("Failed to fetch meeting feedback", err);
          setErrorMsg(
            err?.response?.data?.message ||
              err?.message ||
              "Failed to fetch meeting feedback",
          );
        });
    } else {
      setErrorMsg("");
      setSuccessMsg("");
    }
  }, [selectedMeetingId]);

  const filteredMeetings = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return MEETINGS;
    return MEETINGS.filter(
      (m) =>
        m.name.toLowerCase().includes(q) || m.startup.toLowerCase().includes(q),
    );
  }, [searchQuery]);

  const canSaveNotes = mentorNotes.trim().length > 0;

  const handleSaveNotes = () => {
    if (!canSaveNotes) return;
    setErrorMsg("");
    setSuccessMsg("");
    api
      .post("/notes", {
        entityId: `meeting-${selectedMeetingId}`,
        text: mentorNotes,
        outcome,
      })
      .then(() => {
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      })
      .catch((err) => {
        console.error("Failed to save meeting notes", err);
        setErrorMsg(
          err?.response?.data?.message ||
            err?.message ||
            "Failed to save meeting notes",
        );
      });
  };

  const handleScheduleFollowUp = () => {
    setErrorMsg("");
    setSuccessMsg("");
    api
      .post("/meeting/reschedule", {
        meetingId: selectedMeetingId,
        type: "follow-up",
      })
      .then(() => {
        setSuccessMsg("Follow-up scheduled successfully!");
        setTimeout(() => setSuccessMsg(""), 3000);
      })
      .catch((err) => {
        console.error("Failed to schedule follow-up", err);
        setErrorMsg(
          err?.response?.data?.message ||
            err?.message ||
            "Failed to schedule follow-up",
        );
      });
  };

  return (
    <MentorShell>
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="font-poppins font-bold text-section text-text-heading mb-1">
            Meetings
          </h1>
          <p className="font-inter text-body text-text-muted">
            Manage your mentorship sessions and upcoming meetings.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <ComingSoon
            label="Calendar View"
            position="top"
            inline
            className="inline-flex items-center gap-2 border border-border-subtle text-text-heading font-inter font-medium text-small px-4 py-2 rounded-md"
          >
            <CalendarIcon size={16} strokeWidth={2} />
            Calendar View
          </ComingSoon>
          <ComingSoon
            label="Schedule Meeting"
            position="top"
            inline
            className="inline-flex items-center gap-2 bg-action-bg text-action-text font-poppins font-semibold text-small px-4 py-2 rounded-md"
          >
            <CalendarIcon size={16} strokeWidth={2} />
            Schedule Meeting
          </ComingSoon>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {STATS.map((stat) => (
          <div
            key={stat.label}
            className="bg-surface-white border border-border-subtle rounded-lg p-5 shadow-card"
          >
            <p className="font-inter font-medium text-caption uppercase tracking-wider text-text-muted mb-1">
              {stat.label}
            </p>
            <p className="font-poppins font-semibold text-section text-text-heading">
              {stat.value}
            </p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-5 flex flex-col gap-4">
          <div className="relative">
            <Search
              size={16}
              strokeWidth={2}
              className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted"
            />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by student or startup..."
              className="w-full bg-surface-white border border-border-subtle rounded-md pl-9 pr-3 py-2.5 font-inter text-small focus:outline-none focus:ring-1 focus:ring-brand-black transition-all"
            />
          </div>

          <div className="flex flex-col gap-3">
            {filteredMeetings.map((meeting) => (
              <button
                key={meeting.id}
                type="button"
                onClick={() => setSelectedMeetingId(meeting.id)}
                className={`text-left bg-surface-white border rounded-lg shadow-card p-4 transition-colors ${
                  meeting.id === selectedMeetingId
                    ? "border-brand-black"
                    : "border-border-subtle hover:border-text-muted"
                }`}
              >
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 rounded-full bg-canvas-bg border border-border-subtle shrink-0" />
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between gap-2 mb-0.5">
                      <span className="font-poppins font-semibold text-small text-text-heading truncate">
                        {meeting.name} &bull; {meeting.startup}
                      </span>
                      <Badge variant="neutral" className="shrink-0">
                        {meeting.stage}
                      </Badge>
                    </div>
                    <p className="font-inter text-small text-text-body mb-1">
                      {meeting.title}
                    </p>
                    <Badge variant="info" className="mb-2">
                      {meeting.status}
                    </Badge>
                    <p className="font-inter text-caption text-text-muted flex items-center gap-1">
                      <CalendarIcon size={11} strokeWidth={2} /> {meeting.date}
                    </p>
                    <p className="font-inter text-caption text-text-muted flex items-center gap-1">
                      <Clock size={11} strokeWidth={2} /> {meeting.time}
                    </p>
                    <p className="font-inter text-caption text-text-muted flex items-center gap-1">
                      <Video size={11} strokeWidth={2} /> {meeting.location}
                    </p>
                  </div>
                </div>
                <ComingSoon
                  label="Join Meeting"
                  position="top"
                  inline={false}
                  className="mt-3 flex items-center justify-center bg-action-bg text-action-text font-poppins font-semibold text-caption px-3 py-2 rounded-md"
                >
                  Join Meeting
                </ComingSoon>
              </button>
            ))}
          </div>
        </div>

        {selectedMeeting && (
          <div className="lg:col-span-7 bg-surface-white border border-border-subtle rounded-xl shadow-card p-6">
            {errorMsg && (
              <div className="mb-6 p-3 bg-error/15 border border-error/30 text-error rounded-md text-small flex items-center gap-2">
                <AlertCircle size={16} className="shrink-0" />
                <span>{errorMsg}</span>
              </div>
            )}
            {successMsg && (
              <div className="mb-6 p-3 bg-success/15 border border-success/30 text-success rounded-md text-small flex items-center gap-2">
                <span>{successMsg}</span>
              </div>
            )}
            <div className="flex items-center gap-3 mb-4 pb-4 border-b border-border-subtle">
              <div className="w-12 h-12 rounded-full bg-canvas-bg border border-border-subtle shrink-0" />
              <div>
                <p className="font-poppins font-semibold text-card text-text-heading">
                  {selectedMeeting.name}
                </p>
                <p className="font-inter text-small text-text-muted">
                  {selectedMeeting.college} &bull; {selectedMeeting.startup}
                </p>
                <Badge variant="neutral" className="mt-1">
                  {selectedMeeting.stage} Stage
                </Badge>
              </div>
            </div>

            <div className="flex gap-3 mb-6">
              <ComingSoon
                label="Profile"
                position="top"
                inline
                className="flex-1 flex items-center justify-center bg-action-bg text-action-text font-poppins font-semibold text-small px-4 py-2.5 rounded-md"
              >
                Profile
              </ComingSoon>
              <ComingSoon
                label="Chat"
                position="top"
                inline
                className="flex-1 flex items-center justify-center border border-border-subtle text-text-heading font-inter font-medium text-small px-4 py-2.5 rounded-md"
              >
                Chat
              </ComingSoon>
            </div>

            <p className="font-inter text-caption font-semibold uppercase tracking-wider text-text-muted mb-2">
              Agenda
            </p>
            <ul className="list-disc list-inside font-inter text-small text-text-body mb-4 space-y-1">
              {selectedMeeting.agenda.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>

            <p className="font-inter text-caption font-semibold uppercase tracking-wider text-text-muted mb-2">
              Student Notes
            </p>
            <p className="font-inter text-small text-text-body italic mb-6">
              &quot;{selectedMeeting.studentNotes}&quot;
            </p>

            <label className="font-inter text-caption font-semibold uppercase tracking-wider text-text-muted mb-2 block">
              Mentor Notes
            </label>
            <textarea
              value={mentorNotes}
              onChange={(e) => setMentorNotes(e.target.value)}
              placeholder="Take notes during the session..."
              rows={4}
              className="w-full bg-canvas-bg border border-border-subtle rounded-md p-3 font-inter text-small text-text-body focus:outline-none focus:ring-1 focus:ring-brand-black transition-all resize-none mb-4"
            />

            <label className="font-inter text-caption font-semibold uppercase tracking-wider text-text-muted mb-2 block">
              Meeting Outcome
            </label>
            <select
              value={outcome}
              onChange={(e) => setOutcome(e.target.value)}
              className="w-full bg-canvas-bg border border-border-subtle rounded-md px-3 py-2.5 font-inter text-small text-text-body focus:outline-none focus:ring-1 focus:ring-brand-black transition-all mb-6"
            >
              {OUTCOME_OPTIONS.map((opt) => (
                <option key={opt} value={opt}>
                  {opt}
                </option>
              ))}
            </select>

            <div className="flex items-center gap-3">
              <span
                className={`font-inter text-small text-success transition-opacity duration-150 ${saved ? "opacity-100" : "opacity-0"}`}
                aria-live="polite"
              >
                Saved
              </span>
              <button
                type="button"
                onClick={handleSaveNotes}
                disabled={!canSaveNotes}
                className="bg-action-bg text-action-text font-poppins font-semibold text-small px-5 py-2.5 rounded-md hover:opacity-90 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Save Notes
              </button>
              <button
                type="button"
                onClick={handleScheduleFollowUp}
                className="border border-border-subtle text-text-heading font-inter font-medium text-small px-5 py-2.5 rounded-md hover:bg-canvas-bg transition-colors"
              >
                Schedule Follow-up
              </button>
            </div>
          </div>
        )}
      </div>
    </MentorShell>
  );
}

import { useState } from "react";
import { Link } from "react-router-dom";
import { GraduationCap, Star, Loader2, AlertCircle } from "lucide-react";
import DashboardShell from "@/components/dashboard/DashboardShell";
import Badge from "@/components/ui/Badge";
import { useDocumentTitle } from "@/hooks/useDocumentTitle";
import { mentorshipApi } from "@/api/mentorshipApi";

const INDUSTRY_OPTIONS = [
  "All Industries",
  "FinTech",
  "EdTech",
  "SaaS",
  "HealthTech",
];
const EXPERTISE_OPTIONS = [
  "All Expertise",
  "GTM Strategy",
  "Fundraising",
  "Product Design",
  "Scaling",
];

const MENTORS = [
  {
    id: "m1",
    name: "Sarah Chen",
    role: "Managing Partner at Velocity Ventures",
    rating: "4.9",
    reviews: 42,
    tags: ["SaaS", "GTM Strategy", "Series A"],
    experience: "15+ years",
    mentored: "12 Startups",
    status: "Available",
  },
  {
    id: "m2",
    name: "Marcus Thorne",
    role: "Founder at CloudScale Systems",
    rating: "4.8",
    reviews: 28,
    tags: ["DevOps", "Scalability", "B2B SaaS"],
    experience: "10+ years",
    mentored: "5 Startups",
    status: "Available",
  },
  {
    id: "m3",
    name: "Elena Rodriguez",
    role: "Design Lead at Studio Alpha",
    rating: "5.0",
    reviews: 56,
    tags: ["UX/UI", "Branding", "Product Design"],
    experience: "12+ years",
    mentored: "18 Startups",
    status: "Away",
  },
];

const STATUS_VARIANT = { Available: "success", Away: "neutral" };

export default function MentorDirectoryPage() {
  useDocumentTitle("Mentor Directory — BOCC");
  const [industry, setIndustry] = useState(INDUSTRY_OPTIONS[0]);
  const [expertise, setExpertise] = useState(EXPERTISE_OPTIONS[0]);
  const [mentors, setMentors] = useState(MENTORS);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    async function fetchFiltered() {
      setLoading(true);
      try {
        const filters = {
          industry: industry === "All Industries" ? "" : industry,
          expertise: expertise === "All Expertise" ? "" : expertise,
        };
        const res = await mentorshipApi.filterMentors(filters);
        setMentors(res?.data || []);
      } catch (err) {
        console.error("Failed to filter mentors", err);
        setErrorMsg(
          err?.response?.data?.message ||
            err?.message ||
            "Failed to load mentors.",
        );
        // Fallback to initial mentors if API fails
        setMentors(MENTORS);
      } finally {
        setLoading(false);
      }
    }
    fetchFiltered();
  }, [industry, expertise]);

  return (
    <DashboardShell pageId="mentor-directory">
      <div className="flex items-center gap-3 mb-2">
        <div className="w-10 h-10 rounded-lg bg-brand-black flex items-center justify-center shrink-0">
          <GraduationCap
            size={20}
            strokeWidth={2}
            className="text-accent-neon"
          />
        </div>
        <h1 className="font-poppins font-semibold text-page text-text-heading">
          Mentor Directory
        </h1>
      </div>
      <p className="font-inter text-body text-text-body max-w-2xl mb-6">
        Connect with experienced mentors who can guide you through your startup
        journey.
      </p>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-8">
        <div className="flex flex-col gap-1">
          <label className="text-caption font-medium text-text-heading font-inter">
            Industry
          </label>
          <select
            value={industry}
            onChange={(e) => setIndustry(e.target.value)}
            className="w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] px-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all"
          >
            {INDUSTRY_OPTIONS.map((o) => (
              <option key={o}>{o}</option>
            ))}
          </select>
        </div>
        <div className="flex flex-col gap-1">
          <label className="text-caption font-medium text-text-heading font-inter">
            Expertise
          </label>
          <select
            value={expertise}
            onChange={(e) => setExpertise(e.target.value)}
            className="w-full rounded-md border border-border-subtle bg-surface-white text-sm text-text-body font-inter min-h-[44px] px-3 focus:outline-none focus:border-brand-black focus:ring-1 focus:ring-brand-black transition-all"
          >
            {EXPERTISE_OPTIONS.map((o) => (
              <option key={o}>{o}</option>
            ))}
          </select>
        </div>
      </div>

      {errorMsg && (
        <div className="mb-6 p-3 bg-error/15 border border-error/30 text-error rounded-md text-small flex items-center gap-2">
          <AlertCircle size={16} className="shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {loading ? (
          <div className="col-span-full flex justify-center py-12">
            <Loader2 className="animate-spin text-text-muted" size={32} />
          </div>
        ) : mentors.length === 0 ? (
          <div className="col-span-full text-center py-12 text-text-muted font-inter">
            No mentors found for these filters.
          </div>
        ) : (
          mentors.map((m) => (
            <div
              key={m.id}
              className="bg-surface-white border border-border-subtle rounded-lg p-6 shadow-card flex flex-col"
            >
              <div className="flex justify-between items-start mb-4">
                <div className="w-14 h-14 rounded-lg bg-canvas-bg border border-border-subtle flex items-center justify-center font-poppins font-bold text-body text-text-muted">
                  {m.name
                    .split(" ")
                    .map((n) => n[0])
                    .join("")}
                </div>
                <Badge variant={STATUS_VARIANT[m.status]}>{m.status}</Badge>
              </div>
              <h3 className="font-poppins font-semibold text-card text-text-heading">
                {m.name}
              </h3>
              <p className="font-inter text-small text-text-muted">{m.role}</p>
              <div className="flex items-center gap-1 mt-1 text-warning">
                <Star size={16} strokeWidth={2} fill="currentColor" />
                <span className="font-inter font-semibold text-small text-text-heading">
                  {m.rating}
                </span>
                <span className="font-inter text-small text-text-muted">
                  ({m.reviews} reviews)
                </span>
              </div>
              <div className="flex flex-wrap gap-2 my-4">
                {m.tags.map((t) => (
                  <span
                    key={t}
                    className="px-2 py-1 bg-canvas-bg text-text-muted font-inter text-caption rounded"
                  >
                    {t}
                  </span>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-4 py-4 border-y border-divider-line mb-4">
                <div>
                  <p className="font-inter text-caption text-text-muted uppercase mb-1">
                    Experience
                  </p>
                  <p className="font-inter font-medium text-small text-text-heading">
                    {m.experience}
                  </p>
                </div>
                <div>
                  <p className="font-inter text-caption text-text-muted uppercase mb-1">
                    Mentored
                  </p>
                  <p className="font-inter font-medium text-small text-text-heading">
                    {m.mentored}
                  </p>
                </div>
              </div>
              <div className="flex gap-3 mt-auto">
                <Link
                  to="/mentors/profile"
                  className="flex-1 text-center py-2.5 border border-border-subtle rounded-lg font-inter font-semibold text-small text-text-heading hover:bg-canvas-bg transition-colors"
                >
                  View Profile
                </Link>
                <Link
                  to="/mentors/request"
                  className="flex-1 text-center py-2.5 bg-action-bg text-action-text rounded-lg font-inter font-semibold text-small hover:opacity-90 transition-all"
                >
                  Request
                </Link>
              </div>
            </div>
          ))
        )}
      </div>
      <p className="font-inter text-small text-text-muted mt-6">
        Showing {mentors.length} of 124 mentors
      </p>
    </DashboardShell>
  );
}

import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  ArrowLeft,
  Calendar,
  Zap,
  Lightbulb,
  Loader2,
  AlertCircle,
} from "lucide-react";
import DashboardShell from "@/components/dashboard/DashboardShell";
import Button from "@/components/ui/Button";
import { useDocumentTitle } from "@/hooks/useDocumentTitle";
import { mentorshipApi } from "@/api/mentorshipApi";
import api from "@/api/axiosInstance";

const STAGE_OPTIONS = [
  "Ideation",
  "Prototype / MVP",
  "Early Traction",
  "Scaling",
];
const INDUSTRY_OPTIONS = [
  "SaaS / Enterprise Software",
  "FinTech",
  "HealthTech",
  "CleanTech",
  "EdTech",
];
const MODE_OPTIONS = ["Video Call", "Voice Call", "In-person"];

export default function MentorshipRequestPage() {
  useDocumentTitle("Request Mentorship — BOCC");
  const navigate = useNavigate();
  const [requestStatus, setRequestStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    async function checkStatus() {
      try {
        const res = await mentorshipApi.getMentorshipRequestStatus();
        setRequestStatus(res?.data || null);
      } catch (err) {
        console.error("Failed to get request status", err);
        setErrorMsg(
          err?.response?.data?.message ||
            err?.message ||
            "Failed to check request status.",
        );
      } finally {
        setLoading(false);
      }
    }
    checkStatus();
  }, []);

